// Builtin is a plugin that ships with OpenChat: a known service, set up
// in advance so an administrator only has to finish what is theirs (an
// account with the service, its OAuth app) and switch it on.
type Builtin struct {
	// Key names the definition for good; the row keeps it (plugins.builtin).
	Key         string
	Slug        string
	Name        string
	Description string
	About       string
	Category    string
	IconText    string
	IconColor   string
	// IconInk is the glyph's colour where the brand's is not the dark or
	// white its background would choose; empty for that choice.
	IconInk string
	// IconSlug and IconPath are its Simple Icons icon (simpleicons.org, CC0),
	// the path copied from simple-icons@16.36.0.
	IconSlug string
	IconPath string
	MCPURL   string
	AuthType string
	// HeaderName is the header an administrator's value goes in, for a
	// plugin set up with a key; for one that runs inside OpenChat, only
	// a label (localkit.Options.Secret).
	HeaderName string
	// OAuthScopes are what is asked for when a person connects.
	OAuthScopes string
	// TokenURL is where a person gets their own token, for a plugin that
	// takes one (AuthType "token").
	TokenURL string
	Sort     int32
}

